import math


def _rows(values):
    try:
        materialized = list(values)
    except TypeError as exc:
        raise ValueError("rows must be iterable") from exc
    result = []
    for row in materialized:
        try:
            cells = list(row)
        except TypeError as exc:
            raise ValueError("each row must be iterable") from exc
        if len(cells) != 2:
            raise ValueError("each row must have two values")
        clean = []
        for value in cells:
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
                raise ValueError("features must be finite numbers")
            clean.append(float(value))
        result.append(tuple(clean))
    return result


def fit_centroid_classifier(samples, labels):
    rows = _rows(samples)
    if not rows:
        raise ValueError("samples must not be empty")
    try:
        ys = list(labels)
    except TypeError as exc:
        raise ValueError("labels must be iterable") from exc
    if len(ys) != len(rows):
        raise ValueError("length mismatch")
    if any(isinstance(y, bool) or y not in (0, 1) for y in ys):
        raise ValueError("labels must be 0 or 1")
    if set(ys) != {0, 1}:
        raise ValueError("both classes are required")

    means = tuple(sum(row[i] for row in rows) / len(rows) for i in range(2))
    deviations = []
    for i in range(2):
        variance = sum((row[i] - means[i]) ** 2 for row in rows) / len(rows)
        deviations.append(math.sqrt(variance) or 1.0)
    scales = tuple(deviations)
    standardized = [tuple((row[i] - means[i]) / scales[i] for i in range(2)) for row in rows]
    centroids = {}
    for label in (0, 1):
        group = [row for row, y in zip(standardized, ys) if y == label]
        centroids[label] = tuple(sum(row[i] for row in group) / len(group) for i in range(2))

    def predict(points):
        query = _rows(points)
        output = []
        for row in query:
            point = tuple((row[i] - means[i]) / scales[i] for i in range(2))
            d0 = sum((point[i] - centroids[0][i]) ** 2 for i in range(2))
            d1 = sum((point[i] - centroids[1][i]) ** 2 for i in range(2))
            output.append(0 if d0 < d1 else 1)
        return output

    return predict

